 1  // MapControl — styled with USWDS disaster theme tokens (CSS custom properties).
 2  // All --theme-* vars are defined in dist/disasters.css and available globally.
 3  
 4  .map-control {
 5      position: absolute;
 6      top: 18px;
 7      // right is set via inline style — dynamic offset from top-bar chrome width
 8      display: flex;
 9      flex-direction: column;
10      align-items: flex-end;
11      pointer-events: auto;
12      font-family: var(--theme-font-ui);
13      z-index: 1002;
14  }
15  
16  // ─── Toolbar (transparent wrapper, each feature is its own card) ──────────
17  
18  .map-control__bar {
19      display: flex;
20      flex-direction: row;
21      align-items: center;
22      gap: 10px;
23      white-space: nowrap;
24  }
25  
26  .map-control__group {
27      display: flex;
28      flex-direction: row;
29      align-items: center;
30      background: var(--theme-color-white);
31      border: 1px solid var(--theme-color-base-lighter);
32      border-radius: var(--theme-radius-md);
33      box-shadow: 0 1px 3px var(--theme-color-shadow);
34      overflow: hidden;
35      height: 36px;
36  }
37  
38  .map-control__btn {
39      display: flex;
40      align-items: center;
41      justify-content: center;
42      width: 36px;
43      height: 100%;
44      padding: 0;
45      border: none;
46      cursor: pointer;
47      background: transparent;
48      color: var(--theme-color-ink);
49      flex-shrink: 0;
50      transition: background 0.12s ease, color 0.12s ease;
51

